// the Goods Receiving list opens (at most every 2 minutes per browser). Append to the GR list page's `mounted`.
(() => {
  const WORKER = "2110545675948560386"; // GR_COMPLETE_WORKER
  if (WORKER === "0") return;
  const KEY = "grc_worker_kick_at";
  let last = 0;
  try {
    last = Number(localStorage.getItem(KEY) || 0);
  } catch (e) {}
  if (Date.now() - last < 120000) return;
  try {
    localStorage.setItem(KEY, String(Date.now()));
  } catch (e) {}
  const tick = (round) => {
    try {
      this.runWorkflow(
        WORKER,
        {},
        (w) => {
          const processed = Number((w && w.data && w.data.processed) || 0);
          if (processed > 0) {
            this.refresh();
            if (round < 40) tick(round + 1);
          }
        },
        (e) => console.error("GR Completion V2: worker tick failed", e),
      );
    } catch (e) {
      console.error("GR Completion V2: worker could not be started", e);
    }
  };
  tick(1);
})();","type":"js"},{"key":"refresh","name":"refresh","func":""},{"key":"onParamUpdate","name":"onParamUpdate","func":""},{"key":"onCommentPublish","name":"onCommentPublish","func":""},{"key":"onCommentDelete","name":"onCommentDelete","func":""},{"key":"onMention","name":"onMention","func":""},{"key":"onLoad","name":"onLoad","func":""},{"key":"u9kbu92o","name":"func_u9kbu92o","func":"","type":"rule","rules":[{"key":"mnzg9ou3","action":"openDialog","options":{"condition":"","isCondition":true,"field":"dialog_putshpz4"}}]},{"key":"0i264dh1","name":"func_edit","func":"const status = arguments[0].row.gr_status;

