  this.getComponent(allListID)?.$refs.crud.clearSelection();
  this.refresh();
})();
","type":"js"},{"key":"ige84ydf","name":"func_convertPI","func":"const handleConvertPI = async (
  selectedRecords,
  convertTo,
  isMultiple,
  filterDraft,
) => {
  this.showLoading("Converting Goods Receiving to Purchase Invoice...");
  await this.runWorkflow(
    "2070324857790087170",
    {
      ids: selectedRecords.map((record) => record.id),
      convert_to: convertTo,
      is_multiple: isMultiple,
      filter_draft: filterDraft,
    },
    async (res) => {
      console.log("PI Data", res.data);
      this.$alert(
        "Convert Goods Receiving to Purchase Invoice Success",
        "Success",
        {
          confirmButtonText: "OK",
          type: "success",
        },
      );
      this.refresh();
      this.hideLoading();
    },
    async (err) => {
      console.error(err);
      this.hideLoading();
      if (err.data?.code === 401) {
        // Draft SO cannot be converted.
        await this.$confirm(err.data.msg, "GR cannot be converted.", {
          confirmButtonText: "Proceed",
          type: "warning",
          dangerouslyUseHTMLString: true,
        }).catch(() => {
          console.log("User clicked Cancel or closed the dialog");
          this.hideLoading();
          throw new Error("Converting purchase invoice cancelled.");
        });

        await handleConvertPI(selectedRecords, convertTo, isMultiple, "yes");
      } else if (err.data?.code === 402) {
        // Selected Goods Receiving(s) already has a related Purchase Invoice and cannot be converted.
        await this.$alert(err.data.msg, "Error", {
          confirmButtonText: "OK",
          type: "error",
        });
      } else if (err.data?.code === 403) {
        // All selected Goods Receiving(s) must be from the same plant/organization to create a single Purchase Invoice.
        await this.$confirm(err.data.msg, "", {
          confirmButtonText: "Convert to Multiple PI",
          type: "warning",
          dangerouslyUseHTMLString: true,
        }).catch(() => {
          console.log("User clicked Cancel or closed the dialog");
          this.hideLoading();
          throw new Error("Converting purchase invoice cancelled.");
        });

        await handleConvertPI(
          selectedRecords,
          convertTo,
          "multiple",
          filterDraft,
        );
      }
    },
  );
  this.hideLoading();
};

